-- Extend catalogue, fulfilment, administration and legal configuration.
ALTER TABLE "AdminUser" ADD COLUMN "active" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "Inventory" ADD COLUMN "reserved" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "unitCost" DECIMAL(12,2);
ALTER TABLE "Order" ADD COLUMN "billingAddress" TEXT, ADD COLUMN "companyName" TEXT, ADD COLUMN "invoiceNumber" TEXT, ADD COLUMN "invoiceRequested" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "shippingMethodCode" TEXT NOT NULL DEFAULT 'standard', ADD COLUMN "shippingMethodName" TEXT NOT NULL DEFAULT 'Standard delivery', ADD COLUMN "taxId" TEXT;
ALTER TABLE "Product" ADD COLUMN "careTh" TEXT NOT NULL DEFAULT '', ADD COLUMN "category" TEXT NOT NULL DEFAULT 'Outerwear', ADD COLUMN "categoryTh" TEXT NOT NULL DEFAULT 'เสื้อคลุม', ADD COLUMN "descriptionTh" TEXT NOT NULL DEFAULT '', ADD COLUMN "fitTh" TEXT NOT NULL DEFAULT '', ADD COLUMN "fulfillmentType" TEXT NOT NULL DEFAULT 'ready', ADD COLUMN "materialTh" TEXT NOT NULL DEFAULT '', ADD COLUMN "nameTh" TEXT NOT NULL DEFAULT '', ADD COLUMN "sortOrder" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "weightGrams" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Variant" ADD COLUMN "barcode" TEXT, ADD COLUMN "color" TEXT NOT NULL DEFAULT '', ADD COLUMN "colorHex" TEXT NOT NULL DEFAULT '#111111', ADD COLUMN "colorTh" TEXT NOT NULL DEFAULT '', ADD COLUMN "images" JSONB;
CREATE TABLE "StockReservation" ("id" TEXT NOT NULL, "variantId" TEXT NOT NULL, "sessionKey" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'active', "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "StockReservation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ShippingMethod" ("id" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "nameTh" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "descriptionTh" TEXT NOT NULL DEFAULT '', "fee" DECIMAL(12,2) NOT NULL, "freeAbove" DECIMAL(12,2), "provinceGroup" TEXT NOT NULL DEFAULT 'all', "estimatedDays" TEXT NOT NULL DEFAULT '2–4 business days', "active" BOOLEAN NOT NULL DEFAULT true, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ShippingMethod_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StoreSetting" ("key" TEXT NOT NULL, "value" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "StoreSetting_pkey" PRIMARY KEY ("key"));
CREATE INDEX "StockReservation_sessionKey_status_idx" ON "StockReservation"("sessionKey", "status");
CREATE INDEX "StockReservation_expiresAt_status_idx" ON "StockReservation"("expiresAt", "status");
CREATE UNIQUE INDEX "ShippingMethod_code_key" ON "ShippingMethod"("code");
CREATE UNIQUE INDEX "Variant_barcode_key" ON "Variant"("barcode");
ALTER TABLE "StockReservation" ADD CONSTRAINT "StockReservation_variantId_fkey" FOREIGN KEY ("variantId") REFERENCES "Variant"("id") ON DELETE CASCADE ON UPDATE CASCADE;
